WITH 
x AS ( -- Get list of articles to exclude by vendor request
  SELECT artcl_num AS article_number
  FROM `ld-ds-bi-analytics-prod.bi_dw.vendor_determination`
  WHERE vend_num IN ('0001029097', -- P&G
    '0001027911','0001028734','0001032453', -- Unilever
    '0001033136',--Mondelez
    '0001027908',--Kraft Heinz
    '0001028102','0002606406', -- General Mills
    '0001032450', -- KCC
    '0001028137', -- Cavendish
    '0001008665','0001400186','0001028081', -- PepsiCo Food
    '0001028104' -- Danone
     )),

active AS ( -- If article is active at minimum 1 PCX store, show "Y"
  SELECT article_number, "Y" AS is_active
  FROM `ld-pcx-bia.Merch_PIM.PCX_ACTIVE_ARTICLE_STORES`
  ),

mean AS (
  SELECT DISTINCT ean11, 
    LTRIM(matnr,'0') AS article_number, 
    meinh AS uom, 
    CONCAT(LTRIM(matnr,'0'),"_",meinh) AS liam
  FROM `ld-ds-bi-analytics-prod.cerebro_reporting.sap_ecc_mean`
  WHERE 1=1
    AND DELETED_FLAG = FALSE
    AND LTRIM(matnr,'0') LIKE "2%" -- PCX articles
    AND hpean = "X" -- Only show primary UPC for the liam
),

art AS (
 -- Get list of relevant PCX articles for us excluding irrelevant MCHs and excluding vendors by request
  SELECT artcl_num, 
    sl_uom_cd, 
    CONCAT(artcl_num,"_",sl_uom_cd) AS liam,
    CASE WHEN LENGTH(bse_uom_gtin_cd) >2 THEN bse_uom_gtin_cd END AS bse_uom_gtin_cd
  FROM `lt-dia-lake-prd-consume.product.article_curr`
  LEFT JOIN x ON artcl_num = x.article_number
  WHERE 1=1
    -- Ignore articles besides PCX
    AND artcl_num LIKE "2%"
    -- Ignore MCHs not maintained by PCX Merch team
    AND mch_3_cd NOT IN ('M01', 'M06', 'M08', 'M13', 'M14', 'M99')
    AND mch_2_cd NOT IN ('M0940','M0944','M0945','M1504')
    -- Ignore articles with vendor exclusions
    AND x.article_number IS NULL
    AND bse_uom_gtin_cd NOT IN ('300875134719','56796006528','56796806685','56796906699','56796006597','56796906606','56796006443','56796006610','56796906668','300875134689','56796006078','56796006092','56796805992','56796805985','731124000712','731124000729','731124000736','731124002877','300875134689','56796806685','56796906668','56796006528','300875134719','56796006443','56796006610','56796006597','56796906606','56796906699','363824018386','363824932446','363824954851','363824932453','363824954868','62200816416','62200797760','62200995524','62200825029','801338000096','801338000270','62200798446','62200798439','801338000072','801338000065','62200825036','801338000256','62200904632','62200809951','801338000041','801338000089','801338000102','801338000294','801338000270','363824954813','363824730165','363824720166','363824002323','363824954837','363824989105','67981961942','67981087086','67981087352','67981958997','67981959000','67981984606','67981089486')-- Reckitt excluded products
    AND artcl_num NOT IN ('21589117','21589079','21589322','21590593','21589247','21590060','21589230','21589205','21590568','21589016','21407971','21407931','21207733','21207723',
    '21110749','21119142','21119501','21339008','21589016','21589322','21590568','21589079','21589117','21589230','21589205','21589247','21590060','21590593','21547556','20971453','21314864','20971471','21314668','21225180','20172254001','21509248','20311045001','21368380','21234872','20314822001','21368365','21368308','20311045002','21427868','20944964','20172254002','21431429','21368373','21368392','21431427','21431433','21110749','21119142','21119501','21339008','21589016','21589322','21590568','21589079','21589117','21589230','21589205','21589247','21590060','21590593','21547556','20971453','21314864','20971471','21314668','21225180','20172254001','21509248','20311045001','21368380','21431433','21234872','20314822001','21368365','21368308','20311045002','21427868','20944964','20172254002','21431429','21368373','21368392','21431427','21431433','21049403','20605943','20604747','20605753','20970331','21119637','21474389','20850732','20849136','21293909','21173607','21088748','21540471') -- Reckitt excluded articles
    
    AND artcl_num NOT IN ('21368816','21370169','21370195','21370206','21370217','21434295','21434296','21369080','21369112','21369097','21525082','21370347','21373906','21370323','21577871','21577861','21173379','21588837','21588759','21588887','20659742','21240990','21241012','21241004','21241005','21241017','21241032','21237353','21241020','21241006','21241033','21241014','21241035','21241009','21241040','21241037','21241038','21243985','21434278','21298526','21240849','21240848','21241044','21240843','21369421','21434120','21240703','21240628','21240630','21240659','21240702','21240622','21369419','21434273','21588683','21205756','21205742','21293006','21370205','21370367','21370259','21370222','21524163','21577341','21370460','21370458','21370454','21241053','21241145','21241146','21241052','21240588','21240589','21240603','21240597','21588626','20990644','20991017','21423301','21293080','21205434','20960494','20960497','20972859','20972878','21084988','21370415','21370388','20660270','20659789','20756332002','20899901','21370313','21370317','21370310','21050581','21050575','21050578','21050571','21584933','21584919','21584971','21559709','20027100001','20027100002','21003213','20674094','20125110002','20323883002','20323883001','21517017','21427915','21427916','20163708002','20163708003','20163708004','20163708005','20163708001','20313756001','21575277','21218261','20847434','20847584','21185317','20548640','21239228','21219816','21219824','21219820','21219817','21219815','21294699','21576104','21575967','20150259001','20637403','21009965','20638253','20637355','21384600','21384609','21400403','21391939','21190260','21190265','21190254','21190251','21190266','21551277','21550063','20346597','21400446','20638159','21400447','21550142','21515952','21430834','21550071','21550068','20323113003','20323113002','20323113001','20970661','20053840','20048882','20301064003','20301064001','20301064004','20301064005','20324656002','20301064007','20301064010','21361904','21359366','21359369','21359370','21430773','21359382','21359371','21359377','21359408','21359379','21515953','21430782','20077917','21575494','21575439','20155580','21533500','21529858','20318815002','21244530','21244533','20318815001','20318815003','21529855','21529849','21423301','20797687005','21165508','20609676','20004345','20719512','20018232','20609673','20057536002','20153592002','20141599','20719338','20923400','20609674','20922877','20923501','20923399') -- Pepsico excluded articles
)

SELECT DISTINCT
  art.artcl_num,
  -- Use mean table values if available, otherwise use article_curr
  IFNULL(mean.ean11, art.bse_uom_gtin_cd) AS ean11,
  IFNULL(mean.uom, art.sl_uom_cd) AS uom,
  IFNULL(mean.liam, art.liam) AS liam,
  is_active
FROM art
LEFT JOIN mean ON art.artcl_num = mean.article_number
LEFT JOIN active ON art.artcl_num = active.article_number
WHERE 1=1
  -- Ignore articles with blank or empty UPCs
  AND LENGTH(IFNULL( IFNULL(mean.ean11, art.bse_uom_gtin_cd) ,""))>2
  #NOT REGEXP_CONTAINS(art.sl_uom_cd,r'EA|KG|C\d')
  
ORDER BY 5 DESC, 1,3
